mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 1.6;
  vec3 q = p;
  q.z = mod(q.z, 3.0) - 1.5;
  q.x = abs(q.x) - 2.2;
  float col = length(q.xz) - (0.35 + 0.08 * sin(p.y * 3.0));
  float fl = p.y + 1.4 + 0.02 * sin(p.x * 10.0) * sin(p.z * 10.0);
  float ce = 2.0 - p.y;
  return min(col, min(fl, ce));
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 15.0);
    if (d < 0.003 || t > 16.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.0, 0.06);
  if (t < 16.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(map(pos+e.xyy)-map(pos-e.xyy), map(pos+e.yxy)-map(pos-e.yxy), map(pos+e.yyx)-map(pos-e.yyx)));
    vec3 l = normalize(vec3(0.0, 1.0, -1.0));
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);
    float neon = step(0.85, sin(pos.z * 2.0 + time * 4.0));
    vec3 neonCol = mix(vec3(0.0, 0.9, 1.0), vec3(1.0, 0.1, 0.8), sin(pos.z * 0.4) * 0.5 + 0.5);
    float fog = 1.0 / (1.0 + t * t * 0.02);
    col = (vec3(0.05, 0.02, 0.1) + neon * neonCol * 2.5 + spec * vec3(0.9, 0.8, 1.0)) * fog;
  }
  col += glow * vec3(0.9, 0.1, 0.7) * (0.7 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
